// App.js
import React, { useState } from "react";
import Login from "./Login";
import AdminDashboard from "./AdminDashboard";
import UserShop from "./UserShop";

function App() {
  const [role, setRole] = useState(null);
  const [token, setToken] = useState(null);
  const [message, setMessage] = useState(""); // ✅ we re-added message support

  const handleLogin = (username, password) => {
    if (username === "admin" && password === "pass") {
      setRole("admin");
      setToken("admin_token");
      setMessage("Admin login successful!");
    } else if (username === "user" && password === "pass") {
      setRole("user");
      setToken("user_token");
      setMessage("User login successful!");
    } else {
      setMessage("❌ Invalid credentials");
    }
  };

  const handleLogout = () => {
    setRole(null);
    setToken(null);
    setMessage("You have logged out.");
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans pt-8">
      {message && (
        <div className="bg-indigo-100 text-indigo-800 p-2 text-center mb-4 rounded">
          {message}
        </div>
      )}

      {!role ? (
        <Login onLogin={handleLogin} />
      ) : role === "admin" ? (
        <AdminDashboard token={token} onLogout={handleLogout} />
      ) : (
        <UserShop token={token} onLogout={handleLogout} />
      )}
    </div>
  );
}

export default App;
